def changed_paths(before, after):
    """Return sorted dot-separated paths for additions, removals, or unequal leaves.

    Recurses only where both values are dictionaries.
    Lists and other values are treated atomically.
    String keys never contain dots.
    """
    paths = set()
    _diff(before, after, "", paths)
    return sorted(paths)


def _diff(before, after, prefix, paths):
    for key in before:
        path = f"{prefix}.{key}" if prefix else key
        if key not in after:
            paths.add(path)
        else:
            b_val = before[key]
            a_val = after[key]
            if isinstance(b_val, dict) and isinstance(a_val, dict):
                _diff(b_val, a_val, path, paths)
            else:
                if b_val != a_val:
                    paths.add(path)
    for key in after:
        if key not in before:
            path = f"{prefix}.{key}" if prefix else key
            paths.add(path)
