from bisect import bisect_right


def histogram(edges, values):
    if not isinstance(edges, list) or len(edges) < 2:
        raise ValueError("edges must be a list with at least two numbers")
    for i in range(len(edges) - 1):
        if not isinstance(edges[i], (int, float)) or not isinstance(edges[i + 1], (int, float)):
            raise ValueError("edges must contain only numbers")
        if edges[i] >= edges[i + 1]:
            raise ValueError("edges must be strictly increasing")

    n_bins = len(edges) - 1
    counts = [0] * n_bins

    for v in values:
        if v < edges[0] or v > edges[-1]:
            continue
        idx = min(bisect_right(edges, v) - 1, n_bins - 1)
        counts[idx] += 1

    return counts
