def merge(base, overlay):
    """Recursively merge two JSON-like dictionaries.

    - Overlay values replace base values (including lists, scalars, and None).
    - A None value in overlay does NOT delete the key; it replaces the value with None.
    - Nested dicts are merged recursively.
    - Neither input is mutated; the result is a deep-independent copy.
    """
    result = {}

    # Start with a deep copy of all base entries
    for key, value in base.items():
        result[key] = _deep_copy(value)

    # Apply overlay: replace or recursively merge
    for key, value in overlay.items():
        if key in base and isinstance(base[key], dict) and isinstance(value, dict):
            result[key] = merge(base[key], value)
        else:
            result[key] = _deep_copy(value)

    return result


def _deep_copy(value):
    if isinstance(value, dict):
        return {k: _deep_copy(v) for k, v in value.items()}
    if isinstance(value, list):
        return [_deep_copy(item) for item in value]
    return value
```

