def flatten(value):
    if not value:
        return {}

    result = {}

    for key, val in value.items():
        if isinstance(val, dict):
            if val:
                for sub_key, sub_val in flatten(val).items():
                    result[f"{key}.{sub_key}"] = sub_val
            else:
                result[key] = {}
        else:
            result[key] = val

    return result
