def normalize(path: str) -> str:
    """Normalize an absolute POSIX-like path.

    - Rejects non-absolute paths with ValueError.
    - Collapses repeated slashes.
    - Ignores '.' components.
    - Resolves '..' without going above root.
    - Returns '/' for root, no trailing slash otherwise.
    """
    if not path.startswith("/"):
        raise ValueError(f"Path must be absolute: {path!r}")

    parts = path.split("/")
    stack: list[str] = []

    for part in parts:
        if part == "" or part == ".":
            continue
        if part == "..":
            if stack:
                stack.pop()
            # else: already at root, ignore
        else:
            stack.append(part)

    if not stack:
        return "/"
    return "/" + "/".join(stack)
```

