def pack(items, max_bytes):
    if max_bytes < 1:
        raise ValueError("max_bytes must be >= 1")

    if not items:
        return []

    byte_lengths = [len(item.encode("utf-8")) for item in items]

    for bl in byte_lengths:
        if bl > max_bytes:
            raise ValueError("item does not fit within max_bytes")

    result = []
    current_batch = []
    current_sum = 0

    for item, bl in zip(items, byte_lengths):
        if current_sum + bl > max_bytes:
            result.append(current_batch)
            current_batch = []
            current_sum = 0
        current_batch.append(item)
        current_sum += bl

    if current_batch:
        result.append(current_batch)

    return result
```

