import heapq


def order(deps):
    # Collect all nodes: keys plus any prerequisite-only nodes
    nodes = set(deps.keys())
    for prereqs in deps.values():
        nodes.update(prereqs)

    # Build remaining prerequisite count and reverse adjacency
    remaining = {}
    for node in nodes:
        remaining[node] = len(set(deps.get(node, ())))

    dependents = {node: [] for node in nodes}
    for node, prereqs in deps.items():
        for p in set(prereqs):
            dependents[p].append(node)

    # Seed the min-heap with all nodes that have no prerequisites
    heap = []
    for node in nodes:
        if remaining[node] == 0:
            heapq.heappush(heap, node)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for dependent in dependents[node]:
            remaining[dependent] -= 1
            if remaining[dependent] == 0:
                heapq.heappush(heap, dependent)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected")

    return result
```

